const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taklamakanDesert = ee.Geometry.Polygon(
    [[[78.0, 37.0],
      [78.0, 41.0],
      [88.0, 41.0],
      [88.0, 37.0],
      [78.0, 37.0]]]
  );

  const start2019 = '2019-02-01';
  const end2019 = '2019-02-28';
  const start2020 = '2020-02-01';
  const end2020 = '2020-02-29'; // 2020 was a leap year

  const AOD_BAND = 'Optical_Depth_055'; // AOD at 550nm from MODIS MAIAC

  // 2. Data Acquisition
  const collection = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES');

  // Filter for 2019
  const col2019 = collection
    .filterDate(start2019, end2019)
    .filterBounds(taklamakanDesert);

  // Filter for 2020
  const col2020 = collection
    .filterDate(start2020, end2020)
    .filterBounds(taklamakanDesert);

  const size2019 = await col2019.size().getInfo();
  const size2020 = await col2020.size().getInfo();

  if (size2019 === 0 || size2020 === 0) {
    console.log(`2019 Images: ${size2019}`);
    console.log(`2020 Images: ${size2020}`);
    console.log("C1");
    return;
  }

  // 3. Processing
  // Function to process and get mean AOD for a given collection
  const getMeanAOD = async (collection, yearTag) => {
    // Select the AOD band, scale it, and mask out invalid values.
    const processedImage = collection.select(AOD_BAND)
      .map(image => image.multiply(0.001).updateMask(image.gt(0))) // Scale by 0.001 and mask out values <= 0
      .mean(); // Take the mean over the collection

    const scale = 1000; // Use a reasonable scale to avoid memory errors for large regions
    const maxPixels = 1e9; // Increase maxPixels for potentially large regions

    const stats = await processedImage.reduceRegion({
      reducer: ee.Reducer.mean().setOutputs(['mean']),
      geometry: taklamakanDesert,
      scale: scale,
      maxPixels: maxPixels
    }).getInfo();

    const countStats = await processedImage.reduceRegion({
      reducer: ee.Reducer.count().setOutputs(['count']),
      geometry: taklamakanDesert,
      scale: scale,
      maxPixels: maxPixels
    }).getInfo();

    const aod = stats ? stats['mean'] : null;
    const pixelCount = countStats ? countStats['count'] : 0;

    return { aod: aod, pixelCount: pixelCount, collectionSize: collection.size().getInfo() };
  };

  const data2019 = await getMeanAOD(col2019, '2019');
  const data2020 = await getMeanAOD(col2020, '2020');

  // Check for C2: No valid pixels
  if (data2019.pixelCount === 0 || data2020.pixelCount === 0) {
    console.log(`2019 Images: ${data2019.collectionSize}, Pixels: ${data2019.pixelCount}`);
    console.log(`2020 Images: ${data2020.collectionSize}, Pixels: ${data2020.pixelCount}`);
    console.log("C2");
    return;
  }

  // Check for C3: Calculation failure (NaN, null, or invalid)
  if (data2019.aod === null || isNaN(data2019.aod) || data2020.aod === null || isNaN(data2020.aod)) {
    console.log(`2019 AOD: ${data2019.aod}, Pixels: ${data2019.pixelCount}`);
    console.log(`2020 AOD: ${data2020.aod}, Pixels: ${data2020.pixelCount}`);
    console.log("C3");
    return;
  }

  // 4. Comparison & Final Answer
  const aod2019 = data2019.aod;
  const aod2020 = data2020.aod;

  console.log(`2019 Images: ${data2019.collectionSize}, AOD: ${aod2019.toFixed(3)}, Pixels: ${data2019.pixelCount}`);
  console.log(`2020 Images: ${data2020.collectionSize}, AOD: ${aod2020.toFixed(3)}, Pixels: ${data2020.pixelCount}`);

  if (aod2020 > aod2019) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
